changeSet.sql:
DROP INDEX IF EXISTS trgm_person_name_idx;
CREATE INDEX trgm_person_name_idx
ON person
USING gin (normalize_text(first_name) gin_trgm_ops, normalize_text(last_name) gin_trgm_ops)
WHERE reference_person_id IS NULL;

DROP INDEX IF EXISTS trgm_facility_name_idx;
CREATE INDEX trgm_facility_name_idx
ON facility
USING gin (normalize_text(name) gin_trgm_ops)
WHERE reference_facility_id IS NULL;

DROP INDEX IF EXISTS trgm_contact_name_idx;
CREATE INDEX trgm_contact_name_idx
ON contact
USING gin (normalize_text(name) gin_trgm_ops, normalize_text(first_name) gin_trgm_ops);

DROP INDEX IF EXISTS trgm_inventory_item_name_idx;
CREATE INDEX trgm_inventory_item_name_idx
ON inventory_item
USING gin (normalize_text(name) gin_trgm_ops);

DROP INDEX IF EXISTS trgm_resource_name_idx;
CREATE INDEX trgm_resource_name_idx
ON resource
USING gin (normalize_text(name) gin_trgm_ops);
